import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { LavishPage, LavishStatus } from '../types'
import {
  GLYPH,
  WORD,
  fit,
  isDone,
  authoredFromGrep,
  cleanDescription,
  descFit,
  describePrompt,
  isLive,
  isOwned,
  lavishCalls,
  merge,
  metaDescription,
  nameOf,
  ordered,
  pageTitle,
  parseOpened,
  sanitize,
  sightingsFromTranscript,
  summary,
  visibleText,
  writtenHtml,
} from './lib'
import type { Sighting } from './lib'

const pages = atom({ plugin: 'lavish-pages', key: 'pages' } as const, [])
const isHidden = atom({ plugin: 'lavish-pages', key: 'isHidden' } as const, false)
const isExpanded = atom({ plugin: 'lavish-pages', key: 'isExpanded' } as const, null)
const showClosed = atom({ plugin: 'lavish-pages', key: 'showClosed' } as const, false)
const scanVersion = atom({ plugin: 'lavish-pages', key: 'scanVersion' } as const, 0)
const authored = atom({ plugin: 'lavish-pages', key: 'authored' } as const, [])

/** Bumped when the backfill's rules change, so every session rescans once. */
const SCAN_VERSION = 2
const AUTHORED_MAX = 500

const PANE = 'lavish-pages'
const DEFAULT_BASE = 'http://127.0.0.1:4387'
const REFRESH_MS = 4000
const PENDING_GRACE_MS = 60_000
const AUTO_EXPAND_MAX = 3
const BAND_ROWS_MAX = 6
const STORE_SESSIONS_MAX = 200

const HAIKU = 'claude-haiku-4-5-20251001'
/** Haiku calls running at once, across all pages. */
const DESC_IN_FLIGHT_MAX = 2
/** A page rewritten within this long of its last summary keeps that summary. */
const DESC_REDO_MS = 15 * 60_000
const DESC_STORE_MAX = 300
const READ_MAX = 4 * 1024 * 1024

// ---------- store ----------

const storeKey = async ($: EngineInterface) => `pages:${await $.session.id()}`

const save = async ($: EngineInterface, fn: (list: LavishPage[]) => LavishPage[]) => {
  await update($, pages, list => fn(list ?? []))
  await $.store.set(await storeKey($), { v: 2, pages: await read($, pages) })
}

const prune = async ($: EngineInterface) => {
  const all = await $.store.keys()
  const drop = (prefix: string, max: number) => {
    const keys = all.filter(k => k.startsWith(prefix))
    return keys.slice(0, Math.max(0, keys.length - max))
  }
  for (const k of [...drop('pages:', STORE_SESSIONS_MAX), ...drop('desc:', DESC_STORE_MAX)]) await $.store.delete(k)
}

/** Adds what was found; a page new to this session brings the band back. */
const remember = async ($: EngineInterface, found: readonly Sighting[]) => {
  if (found.length === 0) return
  const before = new Set((await read($, pages)).map(p => p.file))
  await save($, list => merge(list, found))
  if (found.some(f => !before.has(f.file))) await update($, isHidden, () => false)
}

// ---------- backfill: pages this session touched before the mod loaded ----------

const addAuthored = async ($: EngineInterface, files: readonly string[]) => {
  const html = files.filter(f => f.endsWith('.html'))
  if (html.length === 0) return
  await update($, authored, list => [...new Set([...(list ?? []), ...html])].slice(-AUTHORED_MAX))
}

/**
 * Rebuilds the list from the session's transcript: the pages it owns.
 * Resolves false when no transcript file was found.
 */
const scanTranscript = async ($: EngineInterface): Promise<boolean> => {
  const home = (await $.env.get('HOME')) ?? ''
  const cwd = await $.session.cwd()
  const id = await $.session.id()
  const configDir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? `${home}/.claude`

  let main = `${configDir}/projects/${cwd.replace(/[^a-zA-Z0-9]/g, '-')}/${id}.jsonl`
  if (!(await $.fs.exists(main))) {
    const found = await $.process.run(['find', `${configDir}/projects`, '-maxdepth', '2', '-name', `${id}.jsonl`])
    main = found.stdout.split('\n')[0]?.trim() ?? ''
  }

  if (main && (await $.fs.exists(main))) {
    const files = [main]
    const subagents = main.replace(/\.jsonl$/, '') + '/subagents'
    if (await $.fs.exists(subagents)) {
      for (const entry of await $.fs.list(subagents)) {
        if (entry.kind === 'file' && entry.name.endsWith('.jsonl')) files.push(`${subagents}/${entry.name}`)
      }
    }
    // grep, not $.fs.read: transcripts outgrow the 4 MiB read limit; only lavish lines matter.
    const hits = await $.process.run(['grep', '-h', '-F', '-e', 'lavish-axi', '-e', '/session/', ...files], { timeoutMs: 30_000 })
    const writes = await $.process.run(
      ['grep', '-h', '-o', '-E', '"name":"(Write|Edit|MultiEdit)","input":\\{"file_path":"[^"]+\\.html"', ...files],
      { timeoutMs: 30_000 },
    )
    await addAuthored($, authoredFromGrep(writes.stdout.split('\n')))
    const found = sightingsFromTranscript(hits.stdout.split('\n'), home, await read($, authored))
    await save($, () => merge([], found))
    return true
  }

  // No transcript file found: fall back to what the session holds in memory.
  const now = await $.clock.now()
  const messages = await $.session.messages()
  const wrote: string[] = []
  for (const message of messages) {
    for (const use of message.toolUses) {
      const path = use.input.file_path
      if (['Write', 'Edit', 'MultiEdit'].includes(use.tool) && typeof path === 'string') wrote.push(path)
      if (use.tool === 'Bash' && typeof use.input.command === 'string') wrote.push(...writtenHtml(use.input.command, cwd, home))
    }
  }
  await addAuthored($, wrote)
  const mine = new Set(await read($, authored))
  const found: Sighting[] = []
  for (const message of messages) {
    for (const use of message.toolUses) {
      if (use.tool !== 'Bash' || typeof use.input.command !== 'string') continue
      const owned = lavishCalls(use.input.command, cwd, home).filter(c => isOwned(c, mine)).map(c => c.file)
      for (const file of owned) found.push({ file, seenAt: now })
      for (const o of parseOpened(use.text ?? '')) if (owned.includes(o.file)) found.push({ ...o, seenAt: now })
    }
  }
  await remember($, found)
  return false
}

// ---------- status ----------

type LavishSession = {
  key: string
  file: string
  url?: string
  status: string
  ended_by?: string
  pending_prompts?: number
  artifact_revision?: number
}

const baseOf = (list: readonly LavishPage[]): string => {
  const url = list.find(p => p.url)?.url
  if (!url) return DEFAULT_BASE
  try {
    return new URL(url).origin
  } catch {
    return DEFAULT_BASE
  }
}

const refresh = async ($: EngineInterface): Promise<void> => {
  const list = await read($, pages)
  if (list.length === 0) return

  let listeners = new Set<string>()
  let stateDir: string | undefined
  let isAlive = false
  try {
    const res = await $.http.fetch(`${baseOf(list)}/health`)
    if (res.ok) {
      const health = JSON.parse(res.text)
      isAlive = health.ok === true
      stateDir = health.state_dir
      listeners = new Set((health.listeners ?? []).map((l: { key: string }) => l.key))
    }
  } catch {
    isAlive = false
  }
  stateDir ??= `${(await $.env.get('HOME')) ?? ''}/.lavish-axi`

  let sessions: LavishSession[] = []
  try {
    const raw = JSON.parse(await $.fs.read(`${stateDir}/state.json`))
    sessions = Object.values(raw.sessions ?? {}) as LavishSession[]
  } catch {
    sessions = []
  }

  const now = await $.clock.now()
  const next = list.map((page): LavishPage => {
    const s = sessions.find(x => x.file === page.file || (page.key !== undefined && x.key === page.key))
    if (!s) {
      const status: LavishStatus = !isAlive ? 'dead' : now - page.seenAt < PENDING_GRACE_MS ? 'pending' : 'missing'
      return { ...page, status, prompts: 0 }
    }
    let status: LavishStatus
    if (s.status === 'ended') status = 'closed'
    else if (!isAlive) status = 'dead'
    else status = listeners.has(s.key) ? 'streaming' : 'idle'
    return {
      ...page,
      key: s.key,
      url: s.url ?? page.url,
      status,
      endedBy: s.status === 'ended' ? s.ended_by : undefined,
      prompts: s.pending_prompts ?? 0,
      rev: s.artifact_revision,
    }
  })

  if (JSON.stringify(next) !== JSON.stringify(list)) await save($, () => next)
}

// ---------- descriptions ----------

/** Kept in `$.store` (across sessions) under `desc:<file>`, so Haiku runs once per page version. */
type DescCache = { ver: string; desc?: string; at: number; source: 'meta' | 'haiku' | 'none' }

const inFlight = new Set<string>()
let isDescribing = false

const setDesc = async ($: EngineInterface, file: string, ver: string, desc: string | undefined) => {
  await save($, list => list.map(p => (p.file === file ? { ...p, desc: desc ?? p.desc, descVer: ver } : p)))
}

/** Fills in each page's one-line description in the background; never blocks a draw. */
async function describePages($: EngineInterface): Promise<void> {
  if (isDescribing) return
  isDescribing = true
  try {
    for (const page of await read($, pages)) {
      if (inFlight.has(page.file)) continue
      let ver: string
      let size: number
      try {
        const st = await $.fs.stat(page.file)
        if (st.kind !== 'file') continue
        ver = `${Math.round(st.mtimeMs)}:${st.size}`
        size = st.size
      } catch {
        continue
      }
      if (page.descVer === ver) continue

      const key = `desc:${page.file}`
      const cached = (await $.store.get(key)) as DescCache | undefined
      if (cached?.ver === ver) {
        await setDesc($, page.file, ver, cached.desc)
        continue
      }
      if (size > READ_MAX) {
        await setDesc($, page.file, ver, cached?.desc)
        continue
      }
      let html: string
      try {
        html = await $.fs.read(page.file)
      } catch {
        await setDesc($, page.file, ver, cached?.desc)
        continue
      }
      const now = await $.clock.now()
      const meta = metaDescription(html)
      if (meta) {
        await $.store.set(key, { ver, desc: meta, at: now, source: 'meta' } satisfies DescCache)
        await setDesc($, page.file, ver, meta)
        continue
      }
      // A page being rewritten again and again keeps its summary for a while.
      if (cached?.source === 'haiku' && cached.desc && now - cached.at < DESC_REDO_MS) {
        await setDesc($, page.file, ver, cached.desc)
        continue
      }
      if (inFlight.size >= DESC_IN_FLIGHT_MAX) continue
      inFlight.add(page.file)
      void summarize($, page.file, ver, html, cached?.desc).finally(() => inFlight.delete(page.file))
    }
  } finally {
    isDescribing = false
  }
}

async function summarize($: EngineInterface, file: string, ver: string, html: string, previous: string | undefined) {
  const text = visibleText(html)
  let desc: string | undefined
  if (text.length > 40) {
    const res = await $.model.complete({
      model: HAIKU,
      prompt: describePrompt(pageTitle(html), text),
      maxTokens: 80,
      effort: 'low',
      timeoutMs: 60_000,
    })
    desc = res.isAnswered ? cleanDescription(res.text) : undefined
  }
  desc ??= pageTitle(html) ?? previous
  // Failures are cached too (`none`), so a page is not retried until it changes.
  await $.store.set(`desc:${file}`, { ver, desc, at: await $.clock.now(), source: desc ? 'haiku' : 'none' } satisfies DescCache)
  await setDesc($, file, ver, desc)
}

// ---------- drawing ----------

/** One page's row, sized to `columns`. */
function row(
  $: EngineInterface,
  e: Parameters<EngineInterface['ui']['resolve']>[0],
  page: LavishPage,
  columns: number,
  descBelow = false,
) {
  const { Box, Text, Button } = $.ui.resolve(e)
  const run = async (argv: string[], done: string) => {
    const res = await $.process.run(argv, { timeoutMs: 20000 })
    $.ui.toast(res.exitCode === 0 ? done : `lavish: ${(res.stderr || res.stdout).trim().slice(0, 120)}`)
    await refresh($)
  }
  const name = nameOf(page.file)
  const isNarrow = columns < 70
  const label = isNarrow ? `${GLYPH[page.status]} ` : `${GLYPH[page.status]} ${WORD[page.status]}`.padEnd(12)
  const meta = [
    page.prompts > 0 && !isDone(page) ? `${page.prompts} queued` : '',
    page.status === 'closed' && page.endedBy ? `by ${page.endedBy === 'user' ? 'you' : page.endedBy}` : '',
    !isNarrow && page.rev !== undefined ? `r${page.rev}` : '',
  ].filter(Boolean)
  const metaText = meta.length > 0 ? `  ${meta.join(' · ')}` : ''
  const buttons = isLive(page) ? 16 : page.status === 'pending' ? 8 : 20
  const room = Math.max(8, columns - label.length - metaText.length - buttons - 2)
  const nameWidth = Math.min(room, name.length)
  const inline = descBelow ? undefined : descFit(page.desc, room - nameWidth - 3)
  const canOpen = page.url !== undefined && !isDone(page) && page.status !== 'dead'

  return (
    <Box key={`row-${page.file}`} flexDirection="row">
      <Text bold={page.status === 'streaming'} dimColor={!isLive(page)}>
        {label}
      </Text>
      <Button
        key={`name-${page.file}`}
        label={fit(name, nameWidth)}
        plain
        dimColor={isDone(page)}
        onPress={() => page.url && run(['open', page.url], `Opened ${name}`)}
      />
      {inline !== undefined && <Text dimColor>{` · ${inline}`}</Text>}
      {metaText !== '' && <Text dimColor>{metaText}</Text>}
      <Text> </Text>
      {canOpen && <Button key={`open-${page.file}`} label="open" onPress={() => run(['open', page.url!], `Opened ${name}`)} />}
      {isLive(page) && (
        <Button key={`end-${page.file}`} label="end" onPress={() => run(['lavish-axi', 'end', page.file], `Ended ${name}`)} />
      )}
      {(isDone(page) || page.status === 'dead') && (
        <Button
          key={`reopen-${page.file}`}
          label="reopen"
          onPress={() => run(['lavish-axi', page.file, '--reopen'], `Reopened ${name}`)}
        />
      )}
      {(isDone(page) || page.status === 'dead') && (
        <Button key={`forget-${page.file}`} label="forget" dimColor onPress={() => save($, l => l.filter(p => p.file !== page.file))} />
      )}
    </Box>
  )
}

/** The pane's row: the page, then its description on a line of its own. */
function paneRow($: EngineInterface, e: Parameters<EngineInterface['ui']['resolve']>[0], page: LavishPage, columns: number) {
  const { Box, Text } = $.ui.resolve(e)
  const below = descFit(page.desc, columns - 4)
  return (
    <Box key={`pane-${page.file}`} flexDirection="column">
      {row($, e, page, columns, true)}
      {below !== undefined && <Text dimColor wrap="truncate-end">{`    ${below}`}</Text>}
    </Box>
  )
}


export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'lavish-pages',
      description: 'Show the Lavish band again and open the full list of this session\'s Lavish pages',
    })
    if ((await read($, scanVersion)) < SCAN_VERSION) {
      let hasTranscript = false
      try {
        hasTranscript = await scanTranscript($)
      } finally {
        await update($, scanVersion, () => SCAN_VERSION)
      }
      if (!hasTranscript && (await read($, pages)).length === 0) {
        const saved = sanitize(await $.store.get(await storeKey($)))
        if (saved.length > 0) await update($, pages, () => saved)
      }
      void prune($)
    }
    $.clock.every(REFRESH_MS, async () => {
      await refresh($)
      await describePages($)
    })
    await refresh($)
    void describePages($)
    return next(e)
  })

  on('command.run', { command: 'lavish-pages' }, async $ => {
    await update($, isHidden, () => false)
    const list = await read($, pages)
    if (list.length === 0) return { text: 'This session has not opened any Lavish pages yet.' }
    await $.ui.open({ id: PANE, title: 'Lavish pages' })
    return { text: `Lavish: ${summary(list)}` }
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    await addAuthored($, [e.file_path])
    return next(e)
  })

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    await addAuthored($, [e.file_path])
    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const command = String(e.command ?? '')
    if (!command.includes('lavish-axi')) return next(e)

    const cwd = await $.session.cwd()
    const home = (await $.env.get('HOME')) ?? ''
    const now = await $.clock.now()
    await addAuthored($, writtenHtml(command, cwd, home))
    const mine = new Set(await read($, authored))
    const owned = lavishCalls(command, cwd, home).filter(c => isOwned(c, mine)).map(c => c.file)
    // Recorded before the command runs, so a long foreground poll shows at once.
    await remember($, owned.map(file => ({ file, seenAt: now })))
    void refresh($)

    const ran = await next(e)
    if (ran.deny === undefined && typeof ran.text === 'string') {
      await remember($, parseOpened(ran.text).filter(o => owned.includes(o.file)).map(o => ({ ...o, seenAt: now })))
    }
    await refresh($)
    return ran
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const list = ordered(await read($, pages))
    if (e.props.hasSurvey || list.length === 0 || (await read($, isHidden))) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const columns = e.props.bodyColumns
    const expandedSetting = await read($, isExpanded)
    const expanded = expandedSetting ?? list.length <= AUTO_EXPAND_MAX
    const withClosed = await read($, showClosed)

    const header = (
      <Box flexDirection="row">
        <Text bold>lavish </Text>
        <Text dimColor wrap="truncate-end">
          {summary(list)}
          {'  '}
        </Text>
        <Button
          key="toggle"
          label={expanded ? 'collapse' : 'expand'}
          plain
          dimColor
          onPress={() => update($, isExpanded, () => !expanded)}
        />
        <Text> </Text>
        <Button key="hide" label="hide" plain dimColor onPress={() => update($, isHidden, () => true)} />
      </Box>
    )
    if (!expanded) return header

    const active = list.filter(p => !isDone(p))
    const done = list.filter(isDone)
    const candidates = withClosed ? [...active, ...done] : active
    // Header, the closed toggle and the "+N more" line take three rows at most.
    const room = Math.max(1, Math.min(BAND_ROWS_MAX, e.props.maxRows - 3))
    const shown = candidates.slice(0, room)
    const more = candidates.length - shown.length

    return (
      <Box flexDirection="column">
        {header}
        {shown.map(page => row($, e, page, columns))}
        {more > 0 && <Text dimColor>{`  +${more} more · /lavish-pages lists them all`}</Text>}
        {done.length > 0 && (
          <Button
            key="closed"
            label={withClosed ? `hide ${done.length} closed` : `show ${done.length} closed`}
            plain
            dimColor
            onPress={() => update($, showClosed, () => !withClosed)}
          />
        )}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const list = ordered(await read($, pages))
    return (
      <Box flexDirection="column">
        <Text dimColor wrap="truncate-end">
          {summary(list)}
        </Text>
        {list.length === 0 && <Text dimColor>No Lavish pages from this session.</Text>}
        {list.map(page => paneRow($, e, page, e.props.bodyColumns))}
      </Box>
    )
  })
}

