import type { LavishPage, LavishStatus } from '../types'

const SUBCOMMANDS = new Set(['open', 'poll', 'end', 'export', 'share'])

export type Sighting = { file: string; url?: string; seenAt: number }

// ---------- paths and commands ----------

const normalize = (path: string): string => {
  const out: string[] = []
  for (const part of path.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') out.pop()
    else out.push(part)
  }
  return '/' + out.join('/')
}

const resolvePath = (base: string, path: string, home: string): string => {
  if (path.startsWith('~/')) return normalize(home + path.slice(1))
  if (path.startsWith('/')) return normalize(path)
  return normalize(base + '/' + path)
}

const tokens = (segment: string): string[] => {
  const escaped = segment.replace(/\\ /g, '\u0000')
  const found: string[] = []
  for (const m of escaped.matchAll(/"([^"]*)"|'([^']*)'|(\S+)/g)) {
    found.push((m[1] ?? m[2] ?? m[3] ?? '').replace(/\u0000/g, ' '))
  }
  return found
}

export type LavishCall = { file: string; sub: string }

const stripHeredocs = (command: string) =>
  command.replace(/<<-?\s*['"]?(\w+)['"]?[^\n]*\n[\s\S]*?\n\s*\1\s*(?=\n|$)/g, '')

/**
 * Each lavish-axi call in a shell command: the .html file and the subcommand
 * (`open` for a bare `lavish-axi <file>`).
 */
export const lavishCalls = (command: string, cwd: string, home: string): LavishCall[] => {
  let dir = cwd
  const calls: LavishCall[] = []
  // Heredoc bodies are file contents, not commands run.
  for (const segment of stripHeredocs(command).split(/&&|\|\||;|\n|\|/)) {
    const words = tokens(segment)
    const target = words[1]
    if (words[0] === 'cd' && target) {
      dir = resolvePath(dir, target, home)
      continue
    }
    const at = words.findIndex(w => w === 'lavish-axi' || w.endsWith('/lavish-axi'))
    if (at < 0) continue
    const rest = words.slice(at + 1)
    const first = rest[0]
    if (first === undefined) continue
    if (!first.endsWith('.html') && !SUBCOMMANDS.has(first)) continue
    const html = rest.find(w => w.endsWith('.html') && !w.startsWith('-'))
    if (html) calls.push({ file: resolvePath(dir, html, home), sub: first.endsWith('.html') ? 'open' : first })
  }
  return calls
}

/** The .html files a shell command opens, polls, ends, exports or shares with lavish-axi. */
export const lavishFiles = (command: string, cwd: string, home: string): string[] =>
  lavishCalls(command, cwd, home).map(c => c.file)

/** .html files a shell command writes by redirection or tee (`cat > page.html <<EOF`). */
export const writtenHtml = (command: string, cwd: string, home: string): string[] => {
  const files: string[] = []
  for (const m of stripHeredocs(command).matchAll(/(?:>>?|\btee(?:\s+-a)?)\s*("[^"]+\.html"|'[^']+\.html'|[^\s;&|<>]+\.html)/g)) {
    const raw = (m[1] ?? '').replace(/^["']|["']$/g, '')
    if (raw) files.push(resolvePath(cwd, raw, home))
  }
  return files
}

/**
 * Whether a session owns a page: it wrote the file, or it polls it for
 * feedback. Opening, ending or exporting someone else's page is no claim.
 */
export const isOwned = (call: LavishCall, authored: ReadonlySet<string>) =>
  call.sub === 'poll' || authored.has(call.file)

/** `file:` and `url:` from lavish-axi's open output. */
export const parseOpened = (text: string): { file: string; url: string }[] => {
  const found: { file: string; url: string }[] = []
  const re = /file:\s*"?([^"\n]+?\.html)"?\s*\n\s*url:\s*"?(https?:\/\/[^"\s]+)"?/g
  for (const m of text.matchAll(re)) if (m[1] && m[2]) found.push({ file: m[1], url: m[2] })
  return found
}

// ---------- the transcript backfill ----------

type Block = { type?: string; name?: string; input?: { command?: unknown }; content?: unknown; text?: unknown }

const resultText = (content: unknown): string => {
  if (typeof content === 'string') return content
  if (Array.isArray(content)) return content.map(b => (typeof b?.text === 'string' ? b.text : '')).join('\n')
  return ''
}

/** Absolute .html paths from `grep -o` hits on Write/Edit tool calls. */
export const authoredFromGrep = (hits: readonly string[]): string[] =>
  hits.flatMap(h => {
    const m = h.match(/"file_path":"([^"]+\.html)"/)
    return m?.[1] ? [m[1]] : []
  })

/**
 * The Lavish pages a session's transcript lines (JSONL, main and subagents)
 * show it owns: written by it (`authored`, or a shell redirection), or polled.
 */
export const sightingsFromTranscript = (lines: readonly string[], home: string, authored: readonly string[] = []): Sighting[] => {
  const mine = new Set(authored)
  const calls: (LavishCall & { seenAt: number })[] = []
  const urls = new Map<string, string>()
  for (const line of lines) {
    if (!line.includes('lavish-axi') && !line.includes('/session/')) continue
    let row: { cwd?: string; timestamp?: string; message?: { content?: unknown } }
    try {
      row = JSON.parse(line)
    } catch {
      continue // a line cut short by the read limit
    }
    const content = row.message?.content
    if (!Array.isArray(content)) continue
    const seenAt = Date.parse(row.timestamp ?? '') || 0
    for (const block of content as Block[]) {
      if (block.type === 'tool_use' && block.name === 'Bash' && typeof block.input?.command === 'string') {
        const cwd = row.cwd ?? '/'
        for (const file of writtenHtml(block.input.command, cwd, home)) mine.add(file)
        for (const call of lavishCalls(block.input.command, cwd, home)) calls.push({ ...call, seenAt })
      }
      if (block.type === 'tool_result') {
        for (const o of parseOpened(resultText(block.content))) urls.set(o.file, o.url)
      }
    }
  }
  const owned = new Set(calls.filter(c => isOwned(c, mine)).map(c => c.file))
  return calls.filter(c => owned.has(c.file)).map(c => ({ file: c.file, url: urls.get(c.file), seenAt: c.seenAt }))
}

/** Folds sightings into the list: one row per file, newest url and time kept. */
export const merge = (list: readonly LavishPage[], found: readonly Sighting[]): LavishPage[] => {
  const out = [...list]
  for (const f of found) {
    const at = out.findIndex(p => p.file === f.file)
    const known = out[at]
    if (!known) {
      out.push({ file: f.file, url: f.url, status: 'pending', prompts: 0, seenAt: f.seenAt })
      continue
    }
    out[at] = { ...known, url: f.url ?? known.url, seenAt: Math.max(known.seenAt, f.seenAt) }
  }
  return out
}

/** Pages read back from the store, whatever version of the mod wrote them. */
export const sanitize = (saved: unknown): LavishPage[] => {
  const list = Array.isArray(saved) ? saved : (saved as { pages?: unknown })?.pages
  if (!Array.isArray(list)) return []
  return list
    .filter((p): p is Record<string, unknown> => typeof p?.file === 'string')
    .map(p => ({
      file: p.file as string,
      url: typeof p.url === 'string' ? p.url : undefined,
      key: typeof p.key === 'string' ? p.key : undefined,
      status: 'pending' as const,
      prompts: 0,
      seenAt: typeof p.seenAt === 'number' ? p.seenAt : 0,
    }))
}

// ---------- ordering and summaries ----------

const RANK: Record<LavishStatus, number> = { streaming: 0, idle: 1, pending: 2, dead: 3, missing: 4, closed: 5 }

export const isLive = (p: LavishPage) => p.status === 'streaming' || p.status === 'idle'
export const isDone = (p: LavishPage) => p.status === 'closed' || p.status === 'missing'

/** Pages needing you first: queued prompts, streaming, open; closed last; newest first within each. */
export const ordered = (list: readonly LavishPage[]): LavishPage[] =>
  [...list].sort((a, b) => {
    const ra = RANK[a.status] - (a.prompts > 0 && !isDone(a) ? 10 : 0)
    const rb = RANK[b.status] - (b.prompts > 0 && !isDone(b) ? 10 : 0)
    return ra - rb || b.seenAt - a.seenAt
  })

export const GLYPH: Record<LavishStatus, string> = {
  streaming: '●',
  idle: '○',
  closed: '–',
  dead: '✕',
  pending: '…',
  missing: '?',
}

export const WORD: Record<LavishStatus, string> = {
  streaming: 'streaming',
  idle: 'open',
  closed: 'closed',
  dead: 'down',
  pending: 'starting',
  missing: 'gone',
}

/** One line: `7 pages · ● 2 streaming · 3 queued · ○ 1 open · – 4 closed`. */
export const summary = (list: readonly LavishPage[]): string => {
  const count = (s: LavishStatus) => list.filter(p => p.status === s).length
  const queued = list.filter(p => !isDone(p)).reduce((n, p) => n + p.prompts, 0)
  const parts = [`${list.length} page${list.length === 1 ? '' : 's'}`]
  const add = (s: LavishStatus) => {
    const n = count(s)
    if (n > 0) parts.push(`${GLYPH[s]} ${n} ${WORD[s]}`)
  }
  add('streaming')
  if (queued > 0) parts.push(`${queued} queued`)
  add('idle')
  add('pending')
  add('dead')
  add('closed')
  add('missing')
  return parts.join(' · ')
}

export const nameOf = (file: string) => file.split('/').pop() ?? file

/** Cuts a name to `width` cells, keeping its end (the extension) visible. */
export const fit = (text: string, width: number): string => {
  if (text.length <= width) return text
  if (width <= 1) return '…'
  const keep = width - 1
  const tail = Math.min(8, Math.floor(keep / 2))
  return text.slice(0, keep - tail) + '…' + text.slice(text.length - tail)
}

// ---------- descriptions ----------

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'", mdash: '—', ndash: '–', middot: '·', hellip: '…' }

const decode = (text: string) => text.replace(/&(#?\w+);/g, (m, name: string) => ENTITIES[name] ?? m)

const squash = (text: string) => decode(text).replace(/\s+/g, ' ').trim()

/** `<meta name="description" content="…">`, in either attribute order. */
export const metaDescription = (html: string): string | undefined => {
  for (const tag of html.match(/<meta\b[^>]*>/gi) ?? []) {
    if (!/\bname\s*=\s*["']description["']/i.test(tag)) continue
    const content = tag.match(/\bcontent\s*=\s*"([^"]*)"|\bcontent\s*=\s*'([^']*)'/i)
    const text = squash(content?.[1] ?? content?.[2] ?? '')
    if (text) return text
  }
  return undefined
}

export const pageTitle = (html: string): string | undefined => {
  const m = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)
  const text = squash(m?.[1] ?? '')
  return text || undefined
}

/** What a reader sees: scripts, styles, svg and the head dropped, tags stripped. */
export const visibleText = (html: string, max = 4000): string => {
  const body = html
    .replace(/<head\b[\s\S]*?<\/head>/gi, ' ')
    .replace(/<(script|style|svg|noscript|template)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')
  return squash(body).slice(0, max)
}

/** A model's reply cut to one clean line. */
export const cleanDescription = (text: string): string | undefined => {
  const line = text
    .split('\n')
    .map(l => l.trim())
    .find(Boolean)
  const out = (line ?? '')
    .replace(/^(description|summary)\s*:\s*/i, '')
    .replace(/^["'`*]+|["'`*]+$/g, '')
    .replace(/\.$/, '')
    .trim()
  return out ? out.slice(0, 140) : undefined
}

export const describePrompt = (title: string | undefined, text: string) =>
  'Below is the text of an HTML page someone made to review work with an AI assistant.\n' +
  'Write ONE plain-English line, at most 12 words, saying what the page is for ' +
  '(e.g. "Tracks launch tasks and who owns each"). No quotes, no trailing period, nothing else.\n\n' +
  `Title: ${title ?? '(none)'}\n\nText:\n${text}`

/** Where `desc` goes in a row: after the name, or nowhere when it would be a stub. */
export const descFit = (desc: string | undefined, width: number): string | undefined => {
  if (!desc || width < 14) return undefined
  return desc.length <= width ? desc : desc.slice(0, width - 1) + '…'
}

