export type LavishStatus = 'streaming' | 'idle' | 'closed' | 'dead' | 'pending' | 'missing'

export type LavishPage = {
  file: string
  url?: string
  key?: string
  status: LavishStatus
  endedBy?: string
  prompts: number
  /** Lavish's artifact_revision: how many times the page has been rewritten. */
  rev?: number
  /** When this session last touched the page (ms since epoch). */
  seenAt: number
  /** One line saying what the page is for: its meta description, else a Haiku summary. */
  desc?: string
  /** The file version (`mtimeMs:size`) `desc` was last checked against. */
  descVer?: string
}

